class MissingSourceError(ValueError):
    """A claim with no source, or no claim at all."""


def add_citation(entries, claim, url, title, source_text=""):
    """Validate, then append one citation dict to `entries` and return it.

    The dict has the keys claim, url, title and verbatim.
    """
    claim = claim.strip()
    if not claim:
        raise MissingSourceError("a claim cannot be empty")
    if not url.strip():
        raise MissingSourceError(f"refusing to record a claim with no source URL: {claim[:60]!r}")
    citation = {
        "claim": claim,
        "url": url.strip(),
        "title": title,
        "verbatim": bool(source_text) and claim in source_text,
    }
    entries.append(citation)
    return citation
